mapper.select:
    select
    ,
                                           tf.card_no    as tf_card_no,
                                           tf.job_no     as tf_job_no,
                                           tf.job_type   as tf_job_type,
                                           tf.job_status as tf_job_status
from task_flow_weight_item tfwi
         left join task_flow tf on tf.id = tfwi.task_id


            tf.job_no = #{jobNo}


            and tfwi.weight_type = #{weightType}


            and tfwi.weight = #{weight}


            and tfwi.remark like concat('%', #{remark}, '%')


            and tfwi.add_time >= #{startTime}


            and tfwi.add_time <= #{endTime}


    order by tfwi.add_time desc, tfwi.id desc
